  height: 0 !important;
  overflow: hidden !important;
}
/* ======================================
   GLOBAL RESET
====================================== */
* {
  box-sizing: border-box;
}

/* Prevent horizontal page drift on desktop/wide viewports. */
/* On max-width 991px, mobile blocks set html/body overflow-x: visible so bot-check UIs are not clipped. */
html,
body {
  width: 100% !important;
  max-width: 100vw !important;
  overflow-x: hidden !important;
}

/* Fluid media + main columns — keeps PDP/category content inside the viewport */
#if_homepage,
#content_area,
#content_area_home {
  max-width: 100% !important;
  min-width: 0 !important;
}

img,
video {
  max-width: 100% !important;
  max-height: 100% !important;
}

iframe {
  max-width: 100% !important;
}

