/* ===== Vertex Description Flipbook / RH-style ===== */
body.vertex-flipbook-ready #v65-product-parent .gallery{
  display: none !important;
}

body.vertex-flipbook-ready .vertex-desc-flipbook-wrap{
  max-width: 720px;
  margin: 18px auto 28px;
}

body.vertex-flipbook-ready .vertex-flipbook{
  position: relative;
  background: #ffffff;
  border: 1px solid #e9e6e1;
  border-radius: 0;
  overflow: hidden;
  box-shadow: none;
}

body.vertex-flipbook-ready .vertex-flipbook-stage{
  position: relative;
  aspect-ratio: 1 / 1;
  background: #f6f4ef;
  overflow: hidden;
}

body.vertex-flipbook-ready .vertex-flipbook-slide{
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity .22s ease;
  pointer-events: none;
  display: block;
  background: #f6f4ef;
}

body.vertex-flipbook-ready .vertex-flipbook-slide.is-active{
  opacity: 1;
  pointer-events: auto;
  z-index: 2;
}

body.vertex-flipbook-ready .vertex-flipbook-slide img{
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
}

body.vertex-flipbook-ready .vertex-flipbook-ui{
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 56px;
  padding: 0 16px;
  border-top: 1px solid #e9e6e1;
  background: #fff;
  position: relative;
}

body.vertex-flipbook-ready .vertex-flipbook-count{
  font-family: Inter, Arial, sans-serif;
  font-size: 11px;
  line-height: 1;
  font-weight: 500;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: #6e6a64;
}

body.vertex-flipbook-ready .vertex-flipbook-nav{
  position: absolute;
  inset: 0;
  pointer-events: none;
}

body.vertex-flipbook-ready .vertex-flipbook-btn{
  appearance: none;
  border: 0;
  background: transparent;
  color: #4f4a43;
  width: 48px;
  height: 56px;
  border-radius: 0;
  cursor: pointer;
  font-size: 13px;
  line-height: 1;
  transition: opacity .18s ease;
  pointer-events: auto;
  position: absolute;
  top: 0;
}

body.vertex-flipbook-ready .vertex-flipbook-btn:hover{
  opacity: .65;
}

body.vertex-flipbook-ready .vertex-flipbook-btn.vf-prev{
  left: 0;
}

body.vertex-flipbook-ready .vertex-flipbook-btn.vf-next{
  right: 0;
}

body.vertex-flipbook-ready .vertex-flipbook-thumbs{
  display: flex;
  gap: 10px;
  padding: 14px 14px 16px;
  border-top: 1px solid #e9e6e1;
  background: #fff;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
}

body.vertex-flipbook-ready .vertex-flipbook-thumb{
  appearance: none;
  border: 1px solid transparent;
  background: #f6f4ef;
  border-radius: 0;
  padding: 0;
